*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #0f1117;
  --surface:     #1a1d27;
  --surface-hi:  #22263a;
  --border:      #2e3250;
  --border-hi:   #4a5080;
  --accent:      #7c8cf8;
  --accent-dark: #5a68e0;
  --text:        #e2e4f0;
  --text-muted:  #8b8fa8;
  --radius:      10px;
  --transition:  0.22s ease;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.65;
  min-height: 100vh;
}

/* ── Skip link ───────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius);
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 1rem; }

/* ── Page layout ─────────────────────────────────────────── */
header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 2.5rem 1rem 2rem;
  text-align: center;
}

header h1 {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

header p {
  margin-top: 0.5rem;
  color: var(--text-muted);
  font-size: 1.05rem;
}

main {
  max-width: 780px;
  margin: 0 auto;
  padding: 2.5rem 1rem 4rem;
}

/* ── Section headings ────────────────────────────────────── */
.section-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1rem;
}

/* ── FAQ list ────────────────────────────────────────────── */
.faq-list {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

/* ── Example wrapper (required class) ───────────────────── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.example:has(.faq-trigger[aria-expanded="true"]) {
  border-color: var(--border-hi);
}

/* ── Trigger button ──────────────────────────────────────── */
.faq-trigger {
  all: unset;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 1rem;
  padding: 1.1rem 1.25rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  border-radius: var(--radius);
  transition: background var(--transition), color var(--transition);
}

.faq-trigger:hover {
  background: var(--surface-hi);
  color: #fff;
}

/* Visible focus indicator — 2px outline + 3px offset, ≥ 3:1 contrast */
.faq-trigger:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

/* ── Chevron icon ────────────────────────────────────────── */
.faq-icon {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition), color var(--transition);
}

.faq-trigger[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
  color: var(--accent);
}

/* ── Details panel (required class) ─────────────────────── */
.details {
  border-top: 1px solid var(--border);
  padding: 1rem 1.25rem 1.25rem;
  color: var(--text-muted);
  font-size: 0.97rem;
}

.details p + p { margin-top: 0.75rem; }

/* ── Forced colors (Windows High Contrast) ───────────────── */
@media (forced-colors: active) {
  .faq-trigger:focus-visible {
    outline: 2px solid ButtonText;
  }
  .faq-icon { forced-color-adjust: auto; }
}

/* ── Reflow: 320 px ──────────────────────────────────────── */
@media (max-width: 360px) {
  .faq-trigger { padding: 0.9rem 1rem; font-size: 0.95rem; }
  .details      { padding: 0.9rem 1rem 1rem; }
}

/* ── Reduced motion ──────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .faq-trigger, .faq-icon, .example { transition: none; }
}
